using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and our raw SQL
            // queries reference c.Discriminator, so we pin the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id format changed
            // EF8 stored id as "Product|<key>"; EF9 stores just "<key>".
            // Existing documents would become unreachable without this mapping.
            // We add a CosmosId shadow property that reproduces the old format.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // BREAKING CHANGE 3 — HasIndex is no longer silently ignored
            // The Cosmos provider now throws for HasIndex(); removed the old call.
        });
    }
}

/// <summary>
/// Generates the EF Core 8–style "EntityType|Key" id values so existing
/// Cosmos documents stay accessible without a data migration.
/// </summary>
class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

